-- B persisted selection boundary only. No seeds, unlock/rank/instance issuance or old-run migration.
CREATE TABLE IF NOT EXISTS combat_b_selections(account_id TEXT PRIMARY KEY REFERENCES accounts(id) ON DELETE CASCADE,transport_version TEXT NOT NULL,selection_json TEXT NOT NULL CHECK(json_valid(selection_json)),catalog_version TEXT NOT NULL,catalog_revision INTEGER NOT NULL CHECK(catalog_revision>0),revision INTEGER NOT NULL CHECK(revision>0),updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS combat_b_selection_receipts(account_id TEXT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,idempotency_key TEXT NOT NULL,request_hash TEXT NOT NULL,response_json TEXT NOT NULL CHECK(json_valid(response_json)),created_at INTEGER NOT NULL,PRIMARY KEY(account_id,idempotency_key));
CREATE TABLE IF NOT EXISTS combat_b_selection_guard(valid INTEGER NOT NULL CHECK(valid=1));
CREATE TRIGGER IF NOT EXISTS combat_b_receipt_immutable_update BEFORE UPDATE ON combat_b_selection_receipts BEGIN SELECT RAISE(ABORT,'combat_b_receipt_immutable'); END;
CREATE TABLE IF NOT EXISTS combat_b_refit_selections(account_id TEXT PRIMARY KEY REFERENCES accounts(id) ON DELETE CASCADE,transport_version TEXT NOT NULL,definition_hash TEXT NOT NULL,source_hash TEXT NOT NULL,refit_json TEXT NOT NULL CHECK(json_valid(refit_json)),revision INTEGER NOT NULL CHECK(revision>0),updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS combat_b_refit_receipts(account_id TEXT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,idempotency_key TEXT NOT NULL,request_hash TEXT NOT NULL,response_json TEXT NOT NULL CHECK(json_valid(response_json)),created_at INTEGER NOT NULL,PRIMARY KEY(account_id,idempotency_key));
CREATE TABLE IF NOT EXISTS combat_b_refit_guard(valid INTEGER NOT NULL CHECK(valid=1));
CREATE TRIGGER IF NOT EXISTS combat_b_refit_receipt_immutable BEFORE UPDATE ON combat_b_refit_receipts BEGIN SELECT RAISE(ABORT,'combat_b_refit_receipt_immutable'); END;
CREATE TABLE combat_b_account_catalog(account_id TEXT PRIMARY KEY REFERENCES accounts(id),revision INTEGER NOT NULL CHECK(revision BETWEEN 1 AND 9007199254740990),catalog_json TEXT NOT NULL CHECK(json_valid(catalog_json)));
CREATE TABLE combat_b_carriage_instances(account_id TEXT NOT NULL,instance_id TEXT NOT NULL,carriage_id TEXT NOT NULL,revision INTEGER NOT NULL CHECK(revision BETWEEN 1 AND 9007199254740990),PRIMARY KEY(account_id,instance_id),FOREIGN KEY(account_id,carriage_id) REFERENCES account_carriages(account_id,carriage_id));
CREATE TABLE combat_b_account_refit_sources(account_id TEXT PRIMARY KEY REFERENCES accounts(id),revision INTEGER NOT NULL CHECK(revision BETWEEN 1 AND 9007199254740990),selection_revision INTEGER NOT NULL CHECK(selection_revision BETWEEN 1 AND 9007199254740990),source_json TEXT NOT NULL CHECK(json_valid(source_json)));